"""Deterministic offer planning and close decisions using the arena's published cost model."""

from __future__ import annotations

import json
import math
from datetime import date, timedelta
from itertools import product

from .cost_model import OPS, RELATIONSHIP_GOALS, complete_offer, must_haves_ok, total_cost
from .document_reader import supplier_standard_terms
from .play import latest, live_threads, moves_left, standing


class OfferPlanner:
    DISCOUNT = {"leverage": 0.07, "routine": 0.04, "quality_first": 0.015, "stabilise": 0.02, "secure_supply": 0.015}

    def __init__(self, researcher):
        self.researcher = researcher

    def supplier_economics(self, case, supplier_id, standard, research):
        buyer = case["buyer"]
        if buyer.get("category_goal") not in RELATIONSHIP_GOALS or len(case.get("parts", [])) != 1:
            return None
        estimate = next((
            row for row in research["should_cost"]
            if row.get("part_id") == case["parts"][0]
            and row.get("supplier_id") == supplier_id
            and row.get("price") is not None
        ), None)
        if not estimate:
            return None
        card = research["scorecards"].get(supplier_id, {})
        return {
            "full_cost": float(estimate["price"]),
            "interest_rate": float(buyer.get("interest_rate", 0)),
            "usual_rate": float(buyer.get("interest_rate", 0)),
            "ppm": float(card.get("ppm") or standard.get("ppm_commitment") or 0),
            "standard": standard,
        }

    def cost(self, case, terms, standard=None, supplier_id=None, research=None):
        economics = self.supplier_economics(case, supplier_id, standard or {}, research or {}) if research else None
        return total_cost(case, terms, standard, supplier=economics)

    def _choices(self, case, threads, excluded_supplier, research):
        choices = []
        alt = case["buyer"].get("alternative") or {}
        alt_terms = alt.get("terms") or {}
        if alt_terms.get("unit_price") is not None and must_haves_ok(case, alt_terms):
            choices.append((self.cost(case, alt_terms, research=research), "documented alternative"))

        fallback = case["buyer"].get("fallback_unit_price")
        if fallback is not None:
            fallback_terms = complete_offer(case, {"unit_price": float(fallback)})
            if must_haves_ok(case, fallback_terms):
                choices.append((self.cost(case, fallback_terms, research=research), "fallback supply"))

        for sid, events in threads.items():
            if sid == excluded_supplier or sid not in live_threads({sid: events}):
                continue
            sheet_id, terms = standing(events)
            if not sheet_id or terms.get("unit_price") is None:
                continue
            standard = supplier_standard_terms(events)
            if must_haves_ok(case, terms, standard):
                choices.append((self.cost(case, terms, standard, sid, research), f"live quote {sid}"))
        return choices

    def batna(self, case, threads, excluded_supplier, research):
        choices = self._choices(case, threads, excluded_supplier, research)
        return min(choices, default=(math.inf, "no priced alternative"), key=lambda choice: choice[0])

    def target_price(self, case, supplier_id, terms, research):
        buyer = case["buyer"]
        baseline = buyer.get("current_unit_price")
        if baseline is None:
            alternative = buyer.get("alternative") or {}
            baseline = (alternative.get("terms") or {}).get("unit_price")
        if baseline is None:
            case_parts = case.get("parts", [])
            history = [
                row for row in research["purchase_history"]
                if row.get("supplier_id") == supplier_id
                and len(case_parts) == 1 and row.get("part_id") == case_parts[0]
            ]
            history.sort(key=lambda row: row.get("date", ""), reverse=True)
            baseline = history[0].get("price") if history else None
        if baseline is None:
            case_parts = case.get("parts", [])
            history = [
                row for row in research["purchase_history"]
                if len(case_parts) == 1 and row.get("part_id") == case_parts[0]
            ]
            history.sort(key=lambda row: row.get("date", ""), reverse=True)
            baseline = history[0].get("price") if history else None
        if baseline is None:
            baseline = buyer.get("fallback_unit_price") or (terms or {}).get("unit_price") or 1.0

        fair = float(baseline) * (1 + self.researcher.weighted_market_change(research) / 100)
        category = buyer.get("category_goal", "routine")
        target = fair * (1 - self.DISCOUNT.get(category, 0.04))

        # Only a live awarded quote with buyer-compatible terms is a reliable price ceiling.
        case_parts = case.get("parts", [])
        freight = buyer["freight_eur_per_unit"]
        preferred_incoterm = min(freight, key=freight.get)
        today = date.today()
        recent_quotes = [
            row for row in research["quotes"]
            if len(case_parts) == 1 and row.get("part_id") == case_parts[0]
            and row.get("supplier_id") != supplier_id and row.get("price") is not None
            and row.get("awarded") in (True, 1, "true", "TRUE")
            and row.get("payment_days") is not None
            and row["payment_days"] >= buyer.get("reference_payment_days", 0)
            and row.get("lead_time_days") is not None
            and row["lead_time_days"] <= buyer.get("need_lead_time_days", math.inf)
            and row.get("incoterm") == preferred_incoterm
            and not (row.get("tooling_eur") or 0)
            and self._quote_is_valid(row, today)
        ]
        recent_quotes.sort(key=lambda row: row.get("date", ""), reverse=True)
        if recent_quotes:
            target = min(target, float(recent_quotes[0]["price"]))

        if category in RELATIONSHIP_GOALS and len(case.get("parts", [])) == 1:
            estimate = next((
                row for row in research["should_cost"]
                if row.get("part_id") == case["parts"][0]
                and row.get("supplier_id") == supplier_id and row.get("price") is not None
            ), None)
            if estimate:
                sustainable = max(0.0, min(80.0, float(buyer.get("sustainable_margin_pct") or 0)))
                target = max(target, float(estimate["price"]) / max(0.2, 1 - sustainable / 100))
        return round(max(0.01, target), 2)

    @staticmethod
    def _quote_is_valid(quote, today):
        try:
            expires = date.fromisoformat(quote["date"]) + timedelta(days=int(quote["validity_days"]))
        except (KeyError, TypeError, ValueError):
            return False
        return expires >= today

    def _optimize_terms(self, case, terms, standard, supplier_id, research):
        options = case.get("term_options", {})
        fields = [
            field for field in case.get("negotiable", [])
            if field != "unit_price" and options.get(field)
        ]
        if not fields:
            return complete_offer(case, terms)

        best_key, best_terms = None, None
        for values in product(*(options[field] for field in fields)):
            candidate = complete_offer(case, {**terms, **dict(zip(fields, values))})
            if not must_haves_ok(case, candidate, standard):
                continue
            key = (self.cost(case, candidate, standard, supplier_id, research), tuple(map(repr, values)))
            if best_key is None or key < best_key:
                best_key, best_terms = key, candidate
        return best_terms if best_terms is not None else complete_offer(case, terms)

    def _max_price(self, case, template, standard, supplier_id, cap, research):
        if not math.isfinite(cap):
            return float(template.get("unit_price") or 0)
        choices = case.get("term_options", {}).get("unit_price", [])
        if choices:
            feasible = [
                float(price) for price in choices
                if self.cost(case, complete_offer(case, {**template, "unit_price": price}),
                             standard, supplier_id, research) <= cap + 0.01
            ]
            return max(feasible, default=0.01)

        low, high = 0.01, max(10.0, float(template.get("unit_price") or 1) * 8)
        steps, best = 256, None
        previous_price = low
        previous_ok = self.cost(
            case, complete_offer(case, {**template, "unit_price": low}), standard, supplier_id, research
        ) <= cap + 0.01
        if previous_ok:
            best = low
        for step in range(1, steps + 1):
            price = low + (high - low) * step / steps
            candidate = complete_offer(case, {**template, "unit_price": price})
            feasible = self.cost(case, candidate, standard, supplier_id, research) <= cap + 0.01
            if feasible:
                best = price
            elif previous_ok:
                left, right = previous_price, price
                for _ in range(32):
                    mid = (left + right) / 2
                    probe = complete_offer(case, {**template, "unit_price": mid})
                    if self.cost(case, probe, standard, supplier_id, research) <= cap + 0.01:
                        left = mid
                    else:
                        right = mid
                best = max(best or 0.0, left)
            previous_price, previous_ok = price, feasible
        return round(best or 0.01, 2)

    def _within_cap(self, case, terms, standard, sid, cap, research):
        terms = complete_offer(case, terms)
        if self.cost(case, terms, standard, sid, research) <= cap + 0.01:
            return terms
        ceiling = self._max_price(case, terms, standard, sid, cap, research)
        terms["unit_price"] = min(float(terms.get("unit_price") or ceiling), ceiling)
        return complete_offer(case, terms)

    def _packages(self, case, primary, standard, sid, cap, research):
        primary = self._within_cap(case, primary, standard, sid, cap, research)
        packages = []
        if (must_haves_ok(case, primary, standard)
                and self.cost(case, primary, standard, sid, research) <= cap + 0.01):
            packages.append(primary)
        options, allowed = case.get("term_options", {}), set(case.get("negotiable", []))
        musts = case["buyer"].get("must_haves", [])
        uplift = max(0.01, round(float(primary.get("unit_price") or 0) * 0.01, 2))

        def add(candidate):
            candidate = complete_offer(case, candidate)
            if (must_haves_ok(case, candidate, standard)
                    and self.cost(case, candidate, standard, sid, research) <= cap + 0.01
                    and candidate not in packages and len(packages) < 3):
                packages.append(candidate)

        # Show a small set of explicit trades: faster cash or a longer commitment for a price premium.
        for field in ("payment_days", "contract_months"):
            values = options.get(field, [])
            if field not in allowed or not values or len(packages) >= 3:
                continue
            valid = [value for value in values if all(
                OPS[must["op"]](value, must["value"]) for must in musts if must.get("field") == field
            )]
            if not valid:
                continue
            seller_value = min(valid) if field == "payment_days" else max(valid)
            if seller_value == primary.get(field):
                continue
            variant = {**primary, field: seller_value, "unit_price": float(primary.get("unit_price") or 0) + uplift}
            add(variant)
        return packages

    def _state(self, case, sid, events, research):
        sheet_id, offered = standing(events)
        standard = supplier_standard_terms(events)
        terms = dict(offered) if offered.get("unit_price") is not None else {}
        valid = terms.get("unit_price") is not None and must_haves_ok(case, terms, standard)
        cost = self.cost(case, terms, standard, sid, research) if valid else math.inf
        target = self.target_price(case, sid, terms, research)
        goal_terms = self._optimize_terms(case, complete_offer(case, {**terms, "unit_price": target}), standard, sid, research)
        target_cost = self.cost(case, goal_terms, standard, sid, research)
        return {
            "sheet_id": sheet_id, "terms": terms, "valid": valid, "cost": cost,
            "standard": standard, "target": target, "goal_terms": goal_terms, "target_cost": target_cost,
            "status": latest(events).get("status"), "turn": sum(m.get("from") == "buyer" for m in events),
        }

    def _earned_cap(self, case, events, buyer_history, standard, supplier_id, batna_cap, research):
        """Allow a small, count-based concession for each distinct supplier counteroffer."""
        if not buyer_history:
            return batna_cap

        previous_costs = [
            self.cost(case, complete_offer(case, sheet["terms"]), standard, supplier_id, research)
            for sheet in buyer_history[-1].get("term_sheets", [])
            if sheet.get("terms") and sheet["terms"].get("unit_price") is not None
        ]
        if not previous_costs:
            return batna_cap
        previous_buyer_cost = min(previous_costs)

        # Count distinct proposals, not the apparent size of a move in our cost model.
        supplier_offers = {
            json.dumps(sheet["terms"], sort_keys=True, separators=(",", ":"), default=str)
            for message in events if message.get("from") != "buyer"
            for sheet in message.get("term_sheets", [])
            if sheet.get("terms") and sheet["terms"].get("unit_price") is not None
        }
"""Independent implementation of the arena's published buyer cost equation."""

from __future__ import annotations

import math
import operator
from datetime import date

OPS = {"<=": operator.le, "<": operator.lt, ">=": operator.ge, ">": operator.gt,
       "==": operator.eq, "!=": operator.ne}
RELATIONSHIP_GOALS = {"stabilise", "secure_supply"}


def closing_terms(case, offer, supplier_standard=None):
    buyer = case["buyer"]
    freight = buyer["freight_eur_per_unit"]
    terms = {
        "volume_per_year": buyer["need_per_year"],
        "contract_months": round(12 * buyer["horizon_years"]),
        "payment_days": buyer["reference_payment_days"],
        "lead_time_days": buyer["need_lead_time_days"],
        "incoterm": min(freight, key=freight.get),
    }
    for layer in (supplier_standard or {}, case.get("fixed_terms", {}), offer or {}):
        for field, value in layer.items():
            if value is not None or field not in terms:
                terms[field] = value
    return terms


def _horizon_start(case):
    fixed_date = case.get("fixed_terms", {}).get("effective_date")
    options = case.get("term_options", {}).get("effective_date", [])
    value = fixed_date or (min((item for item in options if item), default=None))
    return date.fromisoformat(value) if value else None


def _years(case, terms):
    months = terms["contract_months"]
    requested = months / 12 if months else 1.0
    return min(requested, case["buyer"]["horizon_years"])


def _units_at_old_price(case, terms, years):
    start = _horizon_start(case)
    effective = terms.get("effective_date")
    if not start or not effective:
        return 0.0
    lag = (date.fromisoformat(effective) - start).days / 365
    return terms["volume_per_year"] * min(max(lag, 0.0), years)


def _supplier_value(case, terms, supplier):
    buyer = case["buyer"]
    standard = {**(supplier.get("standard") or {}), **case.get("fixed_terms", {})}
    freight = buyer["freight_eur_per_unit"]
    if standard.get("payment_days") is None:
        standard["payment_days"] = buyer["reference_payment_days"]
    if standard.get("incoterm") is None:
        standard["incoterm"] = min(freight, key=freight.get)
    standard.setdefault("tooling_eur", 0.0)
    closed = closing_terms(case, terms, standard)
    years = _years(case, closed)
    quantity = closed["volume_per_year"] * years
    if quantity <= 0:
        return float(closed["unit_price"])
    at_old_rate = _units_at_old_price(case, closed, years) / quantity
    finance_rate = supplier["interest_rate"]
    payment_factor = 1 - finance_rate * (closed["payment_days"] - standard["payment_days"]) / 360
    advance_cash_factor = 1 + (finance_rate - supplier.get("usual_rate", finance_rate)) * years / 2
    ppm = supplier.get("ppm", standard.get("ppm_commitment") or 0)
    return (
        closed["unit_price"] * (1 - at_old_rate) * payment_factor
        + at_old_rate * (buyer.get("current_unit_price") or 0.0) * payment_factor
        + freight[closed["incoterm"]] - freight[standard["incoterm"]]
        + ((closed.get("tooling_eur") or 0) - (standard.get("tooling_eur") or 0)) / quantity * advance_cash_factor
        - ppm / 1_000_000 * ((closed.get("chargeback_eur_per_complaint") or 0)
                             - (standard.get("chargeback_eur_per_complaint") or 0))
        + supplier.get("extra", 0.0)
    )


def _relationship_penalty(case, terms, supplier):
    buyer = case["buyer"]
    required_margin = buyer.get("sustainable_margin_pct")
    weight = buyer.get("relationship_eur_per_point")
    if (buyer.get("category_goal") not in RELATIONSHIP_GOALS or not weight or not required_margin
            or not supplier or not supplier.get("full_cost")):
        return 0.0
    sale_value = _supplier_value(case, terms, supplier)
    if sale_value <= 0:
        return 0.0
    margin = (sale_value - supplier["full_cost"]) / sale_value * 100
    shortfall = max(0.0, required_margin - margin)
    smooth_loss = shortfall**2 / 10 if shortfall <= 5 else shortfall - 2.5
    return weight * smooth_loss * _years(case, closing_terms(case, terms, supplier.get("standard")))


def must_haves_ok(case, offer, supplier_standard=None):
    terms = closing_terms(case, offer, supplier_standard)
    for rule in case["buyer"].get("must_haves", []):
        value = terms.get(rule["field"])
        if value is None and rule["op"] not in {"==", "!="}:
            return False
        if not OPS[rule["op"]](value, rule["value"]):
            return False
    return True


def snap(case, field, value):
    options = case.get("term_options", {}).get(field)
    if not options or value in options:
        return value
    if isinstance(value, (int, float)) and all(isinstance(item, (int, float)) for item in options):
        return min(options, key=lambda item: (abs(item - value), item))
    return options[0]


def complete_offer(case, offer):
    buyer = case["buyer"]
    freight = buyer["freight_eur_per_unit"]
    defaults = {
        "volume_per_year": buyer["need_per_year"],
        "contract_months": round(12 * buyer["horizon_years"]),
        "payment_days": buyer["reference_payment_days"],
        "lead_time_days": buyer["need_lead_time_days"],
        "incoterm": min(freight, key=freight.get),
    }
    result = {}
    for field in case["negotiable"]:
        value = (offer or {}).get(field, defaults.get(field))
        if value is None:
            options = case.get("term_options", {}).get(field, [])
            value = options[0] if options else None
        value = snap(case, field, value)
        result[field] = round(value, 2) if field == "unit_price" and value is not None else value
    return result


def cost_parts(case, offer, supplier_standard=None, supplier=None):
    buyer = case["buyer"]
    terms = closing_terms(case, offer, supplier_standard)
    if terms.get("unit_price") is None:
        raise ValueError("a priced term sheet is required")
    years = _years(case, terms)
    committed = terms["volume_per_year"] * years
    need = buyer["need_per_year"]
    covered = min(terms["volume_per_year"], need) * years
    old_price_qty = _units_at_old_price(case, terms, years)
    new_price_qty = committed - old_price_qty
    spend = old_price_qty * (buyer.get("current_unit_price") or terms["unit_price"])
    spend += new_price_qty * terms["unit_price"]

    shortfall_qty = max(0.0, need * buyer["horizon_years"] - covered)
    shortfall = shortfall_qty * buyer["fallback_unit_price"]
    freight = buyer["freight_eur_per_unit"][terms["incoterm"]] * committed
    defect_exposure = buyer.get("cost_per_defect", 0) - min(
        terms.get("chargeback_eur_per_complaint") or 0, buyer.get("cost_per_defect", 0)
    )
    quality = committed * (terms.get("ppm_commitment") or 0) / 1_000_000 * defect_exposure

    index_cost = index_risk = 0.0
    clause = terms.get("index_clause")
    if clause:
        change = buyer.get("index_paths", {}).get(clause["series"], 0.0)
        over_band = max(0.0, abs(change) - clause["deadband_pct"] / 100)
        index_cost = new_price_qty * terms["unit_price"] * clause["material_share"] * over_band
        index_cost *= math.copysign(1, change)
        index_risk = (new_price_qty * terms["unit_price"] * clause["material_share"]
                      * buyer.get("index_risk_pct", 0) / 100)

    components = {
        "purchase": spend,
        "uncovered_need": shortfall,
        "fallback_uncertainty": shortfall * buyer.get("fallback_risk_pct", 0) / 100,
        "cash_timing": spend * buyer["interest_rate"]
        * (buyer["reference_payment_days"] - terms["payment_days"]) / 360,
        "freight": freight,
        "late_delivery": buyer.get("late_cost_per_day", 0)
        * max(0, terms["lead_time_days"] - buyer["need_lead_time_days"]),
        "quality": quality,
        "tooling": terms.get("tooling_eur") or 0.0,
        "index_movement": index_cost,
        "index_variance": index_risk,
        "supplier_health": _relationship_penalty(case, terms, supplier),
    }
    return components


def total_cost(case, offer, supplier_standard=None, supplier=None):
    if closing_terms(case, offer, supplier_standard).get("unit_price") is None:
        return math.inf
    return round(sum(cost_parts(case, offer, supplier_standard, supplier).values()), 2)

